package com.example.rpgcreators

import kotlin.random.Random

/** Local authored starting options. House rules, not official D&D class/race traits. */
data class StarterPower(val name: String, val rules: String, val passive: Boolean = false) {
    val usage: String get() = if (passive) "Пассивная" else "1 раз за игровой день"
}
data class StarterSupply(val name: String, val category: String, val description: String, val quantity: Int = 1)
data class StoryMoment(val event: String, val purpose: String, val hook: String)
data class StoryWeave(val origin: String, val moment: StoryMoment, val secret: String, val tone: String) {
    fun narration(race: String, profession: String): String = listOf(
        "Ты принадлежишь к народу «$race». Твой путь начинается совсем не так, как у большинства. $origin",
        when(tone) {
            "Мрачная" -> "Воспоминания об этом времени до сих пор отзываются тревогой: некоторые вопросы лучше бы оставить без ответов."
            "Героическая" -> "Ты верил, что даже маленькое доброе дело способно изменить чью-то судьбу."
            "Необычная" -> "Судьба словно играла с тобой: самые странные совпадения случались именно в самый неподходящий момент."
            else -> "Мир манил тебя дорогами, тайнами и историями, которые ещё предстояло услышать."
        },
        moment.event,
        "Пережитое приводит тебя к судьбе, которую другие называют «$profession». ${moment.purpose}",
        "Однажды, возможно, тебе придётся признаться: $secret"
    ).joinToString("\n\n")
}

