    /** Subraces retain their archetype but one choice reflects their own environment. */
    fun racialPowers(race: String): List<StarterPower> {
        val base = racial.getValue(raceFamily(race))
        val lower = race.lowercase()
        val special = when {
            "лесн" in lower || "лесов" in lower -> s("Тропа лесного народа", "+1 к Выживанию при поиске дороги в лесу.")
            "морск" in lower || "водн" in lower || "речн" in lower -> s("Память прилива", "+1 к Атлетике при плавании и пересечении водоёмов.")
            "горн" in lower || "скал" in lower -> s("Горные тропы", "+1 к Выживанию при поиске пути в горах.")
            "пещер" in lower || "подзем" in lower -> s("Эхо пещер", "+1 к Восприятию при поиске проходов под землёй.")
            "снеж" in lower || "север" in lower || "ледян" in lower -> s("Опыт холодных земель", "+1 к Выживанию при поиске укрытия на холоде.")
            "степн" in lower || "пустын" in lower -> s("След на песке", "+1 к Выживанию в открытой степи или пустыне.")
            "сумер" in lower || "ночн" in lower -> s("Сумеречные привычки", "+1 к Скрытности в полумраке.")
            "пепел" in lower || "пепель" in lower -> s("Знакомый жар", "+1 к Выживанию на выжженной местности.")
            "золот" in lower || "серебр" in lower -> s("Чутьё ремесленника", "+1 к проверкам ремесла, связанным с драгоценными металлами.")
            else -> null
        }
        return if (special == null || special.name in base.map { it.name }) base else base.take(4) + special
    }

