    fun classPowers(profession: String): List<StarterPower> = professional.getValue(classFamily(profession))
    fun attributesFor(profession: String, build: String): Map<String, Int> {
        val prefer = when(build) {
            "Сильный" -> listOf("Сила", "Телосложение", "Мудрость", "Ловкость", "Харизма", "Интеллект")
            "Ловкий" -> listOf("Ловкость", "Мудрость", "Телосложение", "Харизма", "Сила", "Интеллект")
            "Мудрый" -> listOf("Мудрость", "Телосложение", "Ловкость", "Интеллект", "Харизма", "Сила")
            "Умный" -> listOf("Интеллект", "Мудрость", "Телосложение", "Ловкость", "Харизма", "Сила")
            "Харизматичный" -> listOf("Харизма", "Ловкость", "Телосложение", "Мудрость", "Интеллект", "Сила")
            else -> when(classFamily(profession)) {
                "технолог" -> listOf("Интеллект", "Ловкость", "Телосложение", "Мудрость", "Харизма", "Сила")
                "следопыт", "ловкач" -> listOf("Ловкость", "Мудрость", "Телосложение", "Интеллект", "Харизма", "Сила")
                "маг", "некромант" -> listOf("Интеллект", "Телосложение", "Мудрость", "Ловкость", "Харизма", "Сила")
                "друид", "хранитель" -> listOf("Мудрость", "Телосложение", "Сила", "Ловкость", "Харизма", "Интеллект")
                "бард" -> listOf("Харизма", "Ловкость", "Телосложение", "Мудрость", "Интеллект", "Сила")
                else -> listOf("Сила", "Телосложение", "Ловкость", "Мудрость", "Харизма", "Интеллект")
            }
        }
        return prefer.zip(standard).toMap()
    }

    /** Выбор стартовых вещей. Инвентарь у героя есть всегда — рюкзак не требуется.
     *  Описанные возможности предметов разыгрываются вручную; автоматической активации нет.
