    fun weave(tone: String, old: StoryWeave? = null, part: String = "all", random: Random = Random.Default): StoryWeave {
        fun <T> different(list: List<T>, previous: T?): T {
            val pool = list.filter { it != previous }
            return (if (pool.isEmpty()) list else pool).random(random)
        }
        return StoryWeave(
            origin = if (part == "all" || part == "origin" || old == null) different(origins, old?.origin) else old.origin,
            moment = if (part == "all" || part == "moment" || old == null) different(moments, old?.moment) else old.moment,
            secret = if (part == "all" || part == "secret" || old == null) different(secrets, old?.secret) else old.secret,
            tone = tone
        )
    }
